import {pageHeader,backButton,iconButton,backIcon,statCard,disclosure} from '../primitives.js?v=76';
import {matchHeader} from '../components/match-header.js?v=76';
import {moveNavigation} from '../components/move-navigation.js?v=76';
import {matchStatusPanel} from '../components/match-status-panel.js?v=76';
import {analysisBoardTools,analysisInsights} from './analysis.js?v=76';
const analysisIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/></svg>';
const archiveActions=()=>`<div id="archive-heading-actions" hidden><div id="archive-analysis-actions">${iconButton({id:'archive-analysis',label:'Разобрать партию',icon:analysisIcon,variant:'primary',hidden:true})}${iconButton({id:'analysis-retry',label:'Повторить анализ',icon:analysisIcon,hidden:true})}<div id="analysis-progress" hidden>${iconButton({id:'analysis-cancel',label:'Отменить анализ',icon:'<span class="analysis-spinner" aria-hidden="true"></span>'})}</div></div><div id="archive-export-slot"></div><span id="match-settings" hidden></span></div>`;
export const playPage = () => `<section id="play" class="tab" data-page-kind="root">${pageHeader({title:"Игра",titleId:'match-title',className:'game-heading',startContent:iconButton({id:'archive-return',label:'К истории партий',icon:backIcon,hidden:true}),endContent:archiveActions()})}<div class="page-content"><div id="game-ready" class="game-ready"><h2>Сыграем?</h2><div class="actions"><button id="start-game" class="primary">Партия с ИИ</button></div></div><div id="play-stats" class="play-stats" hidden></div><div class="game-grid" id="match-surface" hidden><div class="board-area">${matchHeader()}<p id="status" class="turn-status" aria-live="polite">Ход белых</p><div id="board" class="board" role="group" aria-label="Шахматная доска"></div>${analysisBoardTools()}<div id="analysis-game-controls">${moveNavigation()}</div>${analysisInsights()}<p id="history-notice" class="history-notice" hidden>Вы смотрите прошлую позицию. Вернитесь к текущему ходу, чтобы продолжить.</p></div>${matchStatusPanel()}</div></div></section>`;
